-- Generated by tools/reference/import-catalogs.cs from pinned source files: change that script, not this file.
-- The ONC high-priority drug-drug interactions (Phansalkar et al., 2012) between two ingredients (RxNorm codes, the lower
-- first), from Wikidata's "significant drug interaction" statements (CC0): db/reference/wikidata/onc-high-priority-interactions-2026-11-19.csv.
-- Applied as ehr_owner after db/policies; safe to run again. Sources, versions, licenses and attribution:
-- docs/expansion/reference-data.md. The rows are COPY blocks, as pg_dump writes them: psql loads the file as it
-- stands, and the tests' database through tests/Ehr.Testing/ReferenceData.cs. Tab-separated; \N is a null.
BEGIN;
CREATE TEMPORARY TABLE incoming_drug_interactions (ingredient_a text, ingredient_b text, source text, level text, citation text) ON COMMIT DROP;
SELECT ingredient_a, ingredient_b, source, level, citation FROM incoming_drug_interactions
ON CONFLICT (ingredient_a, ingredient_b, source) DO UPDATE
    SET level = EXCLUDED.level, citation = EXCLUDED.citation
    WHERE (drug_interactions.level, drug_interactions.citation)
        IS DISTINCT FROM (EXCLUDED.level, EXCLUDED.citation);
DELETE FROM ehr.drug_interactions t
WHERE NOT EXISTS (SELECT 1 FROM incoming_drug_interactions i WHERE i.ingredient_a = t.ingredient_a AND i.ingredient_b = t.ingredient_b AND i.source = t.source)
    AND t.source = 'onc';
COMMIT;
